import boto3
from typing import Dict, List, Any

def extract_receipt_data(image_bytes: bytes) -> Dict[str, Any]:
    client = boto3.client('textract')
    response = client.analyze_expense(Document={'Bytes': image_bytes})

    expense_doc = response['ExpenseDocuments'][0]

    merchant = ''
    tax = ''
    total = ''

    for field in expense_doc.get('SummaryFields', []):
        f_type = field.get('Type', {}).get('Text', '')
        f_value = field.get('ValueDetection', {}).get('Text', '')
        if f_type == 'VENDOR_NAME':
            merchant = f_value
        elif f_type == 'TAX':
            tax = f_value
        elif f_type == 'TOTAL':
            total = f_value

    items: List[Dict[str, str]] = []
    for group in expense_doc.get('LineItemGroups', []):
        for line in group.get('LineItems', []):
            item_name = ''
            item_price = ''
            for field in line.get('LineItemExpenseFields', []):
                f_type = field.get('Type', {}).get('Text', '')
                f_value = field.get('ValueDetection', {}).get('Text', '')
                if f_type == 'ITEM':
                    item_name = f_value
                elif f_type in ('PRICE', 'AMOUNT'):
                    item_price = f_value
            if item_name:
                items.append({'name': item_name, 'price': item_price})

    return {
        'merchant': merchant,
        'tax': tax,
        'total': total,
        'items': items
    }
